# Load grids after each demo to track them
import os, glob, re

def load_grids():
    d = os.environ['RLM_SESSION_DIR']
    sessions_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    all_text = open(sessions_file).read().replace('\\n', '\n')
    G = {}
    for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', all_text):
        k, h, w = match[1], int(match[2]), int(match[3])
        grid_text = all_text[match.end():].split('\n')[:h]
        for row in grid_text:
            if all(x.isdigit() for x in row.split()):
                break
        rows = [[int(x) for x in row.split()] for row in grid_text]
        if k not in G and all(len(r) == w for r in rows) and all(all(x.isdigit() for x in r) for r in rows):
            G[k] = rows
    return G

G = load_grids()
print("Available grids:")
for k in sorted(G.keys()):
    print(f"  {k}: {len(G[k])}x{len(G[k][0])}")

