import os, json, html

def grid_to_html_str(rows, class_name='', style=''):
    """Convert a nested list grid to HTML string."""
    if hasattr(style, 'get'):
        style = style.get('font-size', '3px')

    head = f'<tr class="{class_name}"><th>     {style}</th></tr>\n'

    row_fmt = f'<tr class="{class_name}" style="{style}">' + \
              '<th>{val}</th>'.format(val='')

    for cell in rows[0]:
        row_fmt = row_fmt.replace('<th></th>', f'<th>{str(cell)}</th>', 1)

    head += row_fmt + '</tr>\n'

    for row in rows[1:]:
        if isinstance(row, int):
            head += f'<tr class="{class_name}"><td>{row}</td></tr>\n'
            continue

        line_out = row_fmt
        for cell in row:
            line_out = line_out.replace('<th></th>', f'<th>{str(cell)}</th>', 1)
        head += line_out

    return head.replace('{', '{{').replace('}', '}}')

